<?php
namespace App\Http\Controllers;
use App\Models\SiteSetting;
use App\Models\VoiceProviderAccount;
use App\Services\AuditLogService;
use Illuminate\Http\Request;
class ProviderAdminController extends Controller {
 public function updateAi(Request $r){$d=$r->validate(['gemini_api_key'=>'nullable|string|max:500','gemini_model'=>'required|string|max:120','gemini_fallback_model'=>'nullable|string|max:120']);if(filled($d['gemini_api_key']??null))SiteSetting::write('gemini_api_key',trim($d['gemini_api_key']),true);SiteSetting::write('gemini_model',trim($d['gemini_model']));SiteSetting::write('gemini_fallback_model',trim((string)($d['gemini_fallback_model']??'')));app(AuditLogService::class)->record(auth()->id(),'provider.gemini.updated',request()->ip(),['model'=>$d['gemini_model'],'key_replaced'=>filled($d['gemini_api_key']??null)]);return back()->with('status','تنظیمات Gemini ذخیره شد.');}
 public function testVoice(string $provider){$a=VoiceProviderAccount::where('provider',$provider)->firstOrFail();return response()->json(['ok'=>true,'provider'=>$a->provider,'configured'=>filled($a->credentials_array),'enabled'=>$a->enabled,'healthy'=>$a->healthy,'message'=>'اعتبارسنجی شبکه‌ای provider از محیط اجرا و credential واقعی انجام می‌شود؛ این endpoint مقدار secret را برنمی‌گرداند.']);}
 // موتور صوتی Groq Whisper: رایگان، بدون تحریم گوگل، از ایران قابل دسترس. کلید از console.groq.com.
 public function updateGroq(Request $r){$d=$r->validate(['voice_groq_key'=>'nullable|string|max:500']);if(filled($d['voice_groq_key']??null)){SiteSetting::write('voice_groq_key',trim($d['voice_groq_key']),true);app(AuditLogService::class)->record(auth()->id(),'provider.groq.updated',request()->ip(),['key_replaced'=>true]);}else{SiteSetting::write('voice_groq_key','');}return back()->with('status','تنظیمات موتور صوتی Groq ذخیره شد.');}
 public function testGroq(){try{$key=(string)(SiteSetting::read('voice_groq_key')?:env('GROQ_API_KEY',''));if(trim($key)==='')return response()->json(['ok'=>false,'message'=>'کلید Groq وارد نشده است.']);$resp=\Illuminate\Support\Facades\Http::withHeaders(['Authorization'=>'Bearer '.trim($key)])->timeout(20)->get('https://api.groq.com/openai/v1/models');if($resp->successful()){foreach($resp->json('data',[]) as $m){if(str_contains((string)($m['id']??''),'whisper'))return response()->json(['ok'=>true,'message'=>'اتصال Groq Whisper برقرار است ('.$m['id'].').']);}}return response()->json(['ok'=>false,'message'=>'کلید پذیرفته شد ولی مدل whisper یافت نشد.']);}catch(\Throwable $e){return response()->json(['ok'=>false,'message'=>'خطای اتصال: '.substr($e->getMessage(),0,120)]);}}catch(\Throwable $e){return response()->json(['ok'=>false,'message'=>'خطای غیرمنتظره.']);}}
}
